const $ = (s,root=document)=>root.querySelector(s);
const esc = v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={cap:'M3 9l9-5 9 5-9 5-9-5zm4 3v5c3 3 7 3 10 0v-5m4-3v8',dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',book:'M4 4h6l2 2 2-2h6v15h-6l-2 2-2-2H4zM12 6v15',file:'M6 3h8l4 4v14H6zM14 3v5h4M9 12h6m-6 4h6',calendar:'M5 5h14v16H5zM8 3v4m8-4v4M5 10h14m-11 4h2m4 0h2m-8 4h2',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-4M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8zm8 1a4 4 0 0 1 0 7',chart:'M4 3v18h17M8 16v-5m5 5V7m5 9v-8',chat:'M21 11a8 8 0 0 1-8 8H8l-5 3V11a9 9 0 0 1 18 0zM7 10h10m-10 4h7',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8zM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',archive:'M3 3h18v5H3zM5 8v13h14V8M9 12h6',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'M9 5l7 7-7 7',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14zm5 12 6 6',logout:'M9 3H4v18h5m6-15 6 6-6 6M9 12h12',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zm0 4v5l3 2',check:'M5 12l4 4L19 6',qr:'M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h3v3h3v3h-6zm6-3v3',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',close:'M6 6l12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',video:'M3 6h12v12H3zM15 10l6-4v12l-6-4',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2'};
const icon = name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
const brand = ()=>`<div class="brand"><span class="brand-mark">${icon('cap')}</span><span>SmartClass<small>LEARN. CONNECT. GROW.</small></span></div>`;
let S=null,page='dashboard',classId=null,tab='stream',search='',chart=null,quizTimer=null,chatTarget=null,monthOffset=0;
const titles={dashboard:'Overview',classes:'My classes',assignments:'Assignments',attendance:'Attendance',quizzes:'Quizzes & polls',analytics:'Analytics',calendar:'Calendar',materials:'Learning materials',messages:'Messages',notifications:'Notifications',archive:'Archived classes',profile:'Profile & settings',guardian:'Guardian access',ai:'AI learning assistant',class:'Classroom'};
const teacher=()=>S.user.role==='teacher';
const student=()=>S.user.role==='student';
const activeClasses=()=>S.classes.filter(c=>!c.archivedAt);
const cls=id=>S.classes.find(c=>c.id===id);
const person=id=>id===S.user.id?S.user:S.contacts.find(u=>u.id===id)||{name:'Class member'};
const initials=name=>name.split(' ').slice(0,2).map(n=>n[0]).join('').toUpperCase();
const fmt=v=>new Date(v).toLocaleDateString('en-GB',{day:'numeric',month:'short'});
const time=v=>new Date(v).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
const percent=n=>n===null||n===undefined?'—':n+'%';
const average=key=>{const a=S.analytics.map(x=>x[key]).filter(x=>x!==null);return a.length?Math.round(a.reduce((x,y)=>x+y,0)/a.length):null;};
const btn=(text,action,ico='',kind='secondary',attrs='')=>`<button class="btn ${kind}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${text}</button>`;
const empty=(title,text,action='')=>`<div class="empty">${icon('book')}<h3>${title}</h3><p>${text}</p>${action}</div>`;
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),3500);}
async function api(url,data,method='POST'){const r=await fetch('/api'+url,{method:data===undefined?'GET':method,headers:data instanceof FormData?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:data instanceof FormData?data:JSON.stringify(data)});const contentType=r.headers.get('content-type')||'';if(!contentType.includes('application/json')){const local=['localhost','127.0.0.1','[::1]'].includes(location.hostname)||location.protocol==='file:';throw Error(local?'Login server is not connected. Run npm start and open http://localhost:3000.':'The login service returned an unexpected response. Reload the page and try again. If it continues, check that you are using the current site link.');}let json;try{json=await r.json();}catch{throw Error('The server returned an invalid response. Please try again.');}if(!r.ok){if(r.status===401&&S){S=null;renderAuth();}throw Error(json.error||'Request failed.');}return json;}
async function refresh(){S=await api('/state');sessionStorage.setItem('smartclass-user',S.user.id);localStorage.setItem('smartclass-offline-'+S.user.id,JSON.stringify({user: S.user,assignments:S.assignments}));}
function goto(p,cid){page=p;search='';if(cid){classId=cid;tab='stream';}if(quizTimer){clearInterval(quizTimer);quizTimer=null;}render();window.scrollTo(0,0);}
function renderAuth(register=false){$('#app').innerHTML=`<div class="auth"><section class="auth-story">${brand()}<div class="auth-main"><span class="pill">A LITTLE MORE CONNECTED. A LOT MORE POSSIBLE.</span><h1>Great learning.<br>One <span>smart</span><br>classroom.</h1><p>A shared space for curious minds. Bring your classes, conversations, and progress together.</p><div class="auth-features"><span>${icon('book')}Organized learning</span><span>${icon('users')}Connected classrooms</span><span>${icon('chart')}Meaningful progress</span></div></div><footer>SmartClass LMS · Built for your next chapter.</footer></section><section class="auth-form-wrap"><div class="auth-card"><h2>${register?'Create your account':'Welcome back'}</h2><p>${register?'A better learning experience starts with you.':'Your classroom is ready. Let’s get you settled in.'}</p><form id="auth-form">${register?field('Full name','name','text','',true):''}${field('Email address','email','email','',true)}${register?field('Password','password','password','',true):'<label class="field">Password (any password)<input name="password" type="password" autocomplete="off"></label><p class="help">Use any email and password. New emails automatically create a Student account.</p>'}${register?select('I am a','role',[['student','Student'],['teacher','Teacher'],['guardian','Guardian']]):''}<div id="auth-error"></div><button class="btn primary" type="submit">${register?'Create account':'Sign in'} ${icon('arrow')}</button></form><div class="auth-switch">${register?'Already have an account?':'New to SmartClass?'} <button class="text-btn" data-action="auth-switch" data-register="${!register}">${register?'Sign in':'Create an account'}</button></div><div class="auth-demo"><span class="eyebrow">EXPLORE THE DEMO</span><div class="demo-buttons">${['teacher','student','guardian'].map(r=>btn(r[0].toUpperCase()+r.slice(1),'demo','','secondary',`data-role="${r}"`)).join('')}</div><small class="muted">Any password works for sign-in.</small></div></div></section></div>`;$('#auth-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));const submit=e.target.querySelector('button');submit.disabled=true;try{await api('/auth/'+(register?'register':'login'),b);await refresh();goto('dashboard');await checkAttendanceLink();}catch(err){$('#auth-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;}finally{submit.disabled=false;}};}
function navItem(p,i){return `<button class="nav-item ${page===p||page==='class'&&p==='classes'?'active':''}" data-action="nav" data-page="${p}">${icon(i)}<span>${titles[p]}</span>${p==='classes'?`<span class="count">${activeClasses().length}</span>`:p==='notifications'&&S.notifications.some(n=>!n.read)?`<span class="count">${S.notifications.filter(n=>!n.read).length}</span>`:''}</button>`;}
function render(){if(!S)return renderAuth();if(chart){chart.destroy();chart=null;}$('#app').innerHTML=`<aside class="sidebar">${brand()}<div class="nav-label">WORKSPACE</div>${navItem('dashboard','dashboard')}${navItem('classes','book')}${navItem('assignments','file')}${navItem('attendance','qr')}${navItem('quizzes','check')}${navItem('analytics','chart')}<div class="nav-label">CONNECT & ORGANIZE</div>${navItem('calendar','calendar')}${navItem('materials','book')}${S.user.role!=='guardian'?navItem('messages','chat'):''}${navItem('guardian','shield')}${navItem('notifications','bell')}<div class="side-bottom"><div class="side-promo"><strong>${icon('spark')} A little help goes a long way</strong><p>Find your next step with your learning assistant.</p><button class="text-btn" data-action="nav" data-page="ai">Meet your AI assistant ${icon('arrow')}</button></div>${navItem('archive','archive')}${navItem('profile','settings')}<div class="user-block"><div class="avatar">${esc(initials(S.user.name))}</div><div><strong>${esc(S.user.name)}</strong><small>${S.user.role} account</small></div><button class="icon-btn" data-action="logout" title="Sign out" aria-label="Sign out">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span>Workspace</span>${icon('chevron')}<strong>${titles[page]}</strong></div><div class="top-actions"><label class="search">${icon('search')}<input id="global-search" aria-label="Search classes and assignments" placeholder="Search your workspace…" value="${esc(search)}"></label><button class="icon-btn" data-action="nav" data-page="notifications" title="Notifications" aria-label="Notifications">${icon('bell')}${S.notifications.some(n=>!n.read)?'<i class="dot"></i>':''}</button><button class="avatar" data-action="nav" data-page="profile" title="Your profile">${esc(initials(S.user.name))}</button></div></header><div class="content"><div id="page-content"></div><footer class="footer"><span>© ${new Date().getFullYear()} SmartClass. A space to grow.</span><span>Made for meaningful learning ✧</span></footer></div></main>${page!=='ai'?`<button class="ai-fab" data-action="nav" data-page="ai">${icon('spark')} Ask SmartClass</button>`:''}`;renderPage();$('#global-search').oninput=e=>{search=e.target.value.toLowerCase();renderPage();};}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function renderPage(){if(chart){chart.destroy();chart=null;}const views={dashboard:dashboard,classes:classesView,class:classView,assignments:assignmentsView,attendance:attendanceView,quizzes:quizzesView,analytics:analyticsView,calendar:calendarView,materials:materialsView,messages:messagesView,notifications:notificationsView,archive:archiveView,profile:profileView,guardian:guardianView,ai:aiView};$('#page-content').innerHTML=search?searchView():(views[page]||dashboard)();if($('#performance-chart'))drawChart();if(page==='profile')$('#profile-form').onsubmit=async e=>{e.preventDefault();await act(()=>api('/profile',Object.fromEntries(new FormData(e.target))),'Profile updated.');};if(page==='messages')bindChat();if(page==='ai')bindAI();}
function stat(label,value,ico,foot){return `<div class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-number">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function dashboard(){const pending=teacher()?S.submissions.filter(s=>s.grade===null).length:S.assignments.filter(a=>!S.submissions.some(s=>s.assignmentId===a.id)).length;return heading('Dashboard',`A little clarity for your ${teacher()?'teaching':'learning'} day.`,`${btn(teacher()?'Create class':student()?'Join a class':'Link student',teacher()?'create-class':student()?'join-class':'link-student','plus','primary')}`)+`<section class="welcome"><div><div class="eyebrow">YOUR CLASSROOM, CONNECTED</div><h2>Hello, ${esc(S.user.name.split(' ')[0])} <span style="font-size:23px">✦</span></h2><p>${teacher()?'Inspire a little curiosity. Make a little progress.':student()?'Every small step is a step forward. Make today count.':'Stay close to the moments that shape their learning.'}<br>${activeClasses().length?`You have ${activeClasses().length} active classes in your workspace.`:'Your next chapter starts with a connected classroom.'}</p>${btn(teacher()?'View my classes':'Explore my workspace','nav','arrow','primary small','data-page="classes"')}</div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="book"></div><div class="art-square">${icon('cap')}</div><div class="art-square two">${icon('check')}</div><span class="spark">✦</span></div></section><section class="stats">${stat('Active classes',activeClasses().length,'book','Your connected learning spaces')}${stat(teacher()?'Total students':'Average grade',teacher()?new Set(activeClasses().flatMap(c=>c.students)).size:percent(average('average')),'users',teacher()?'Across your active classrooms':'Based on graded assignments')}${stat(teacher()?'To review':'Pending assignments',pending,'file',pending?'A few things need your attention':'<span>All caught up</span>')}${stat('Attendance rate',percent(average('attendance')),'chart',average('attendance')===null?'Start a session to see attendance':'Across recorded class days')}</section><div class="section-head"><h2>My classes <small>${activeClasses().length} active</small></h2><button class="text-btn" data-action="nav" data-page="classes">View all classes ${icon('arrow')}</button></div><div class="class-grid">${activeClasses().slice(0,3).map(classCard).join('')||empty('Your classroom awaits','Create or join a class to get started.')}</div><div class="columns"><div><section class="panel"><div class="section-head"><h2>${teacher()?'Upcoming assignments':'Your assignments'}</h2><button class="text-btn" data-action="nav" data-page="assignments">View all ${icon('arrow')}</button></div>${S.assignments.slice().sort((a,b)=>Date.parse(a.due)-Date.parse(b.due)).slice(0,3).map(assignmentRow).join('')||empty('A clean slate','Assignments will appear here.')}</section><section class="panel"><div class="section-head"><h2>Learning at a glance</h2><span class="pill">Current progress</span></div><div class="chart-wrap"><canvas id="performance-chart" aria-label="Grade, attendance, quiz and submission percentages" role="img"></canvas></div></section></div><div><section class="panel"><div class="section-head"><h2>Quick actions</h2><span class="muted">↗</span></div>${[['attendance','qr',teacher()?'Start attendance':'Check in to class','A quick scan. A connected classroom.'],['quizzes','check','Quizzes & polls','Make learning a conversation.'],['calendar','calendar','Your schedule','Keep the next step in sight.']].map(([p,i,t,s])=>`<div class="list-row"><span class="row-icon">${icon(i)}</span><div class="row-main"><h3>${t}</h3><p>${s}</p></div><button class="icon-btn" data-action="nav" data-page="${p}" aria-label="${t}">${icon('chevron')}</button></div>`).join('')}</section><section class="panel"><div class="section-head"><h2>Classroom activity</h2><span class="pill green">Latest</span></div>${S.posts.slice(0,3).map(p=>`<div class="activity"><p>${esc(cls(p.classId)?.name)}<br><span class="muted">New classroom announcement</span></p><small>${fmt(p.createdAt)} · ${time(p.createdAt)}</small></div>`).join('')||'<p class="muted">Your classroom activity will appear here.</p>'}<button class="text-btn" data-action="nav" data-page="notifications">All notifications ${icon('arrow')}</button></section></div></div>`;}
function classCard(c){return `<article class="class-card" style="--class-color:${esc(c.color)}"><div class="class-cover"><span class="subject">${esc(c.subject)}</span><h3>${esc(c.name)}</h3><p>Section ${esc(c.section)} · ${esc(c.room||'Online classroom')}</p></div><div class="class-body"><div class="class-meta"><span>${icon('users')}${c.students.length} student${c.students.length===1?'':'s'}</span><span>${icon('file')}${S.assignments.filter(a=>a.classId===c.id).length} assignments</span></div><div class="class-bottom"><span>${teacher()?`Code: <strong>${esc(c.code)}</strong>`:esc(person(c.teacherId).name)}</span><button class="text-btn" data-action="open-class" data-id="${c.id}">Open class ${icon('arrow')}</button></div></div></article>`;}
function classesView(){return heading('Your learning spaces','A home for every subject, and every new idea.',teacher()?btn('Create class','create-class','plus','primary'):student()?btn('Join a class','join-class','plus','primary'):'')+`<div class="class-grid">${activeClasses().map(classCard).join('')}</div>`+(!activeClasses().length?empty('No classes yet','Create, join, or link a student to see classes here.'):'');}
function classView(){const c=cls(classId);if(!c)return empty('Class not found','Return to your classes.');const names={stream:'Stream',classwork:'Classwork',people:'People',materials:'Materials',grades:'Grades'};return `<div class="class-hero" style="--class-color:${esc(c.color)}"><span class="subject">${esc(c.subject)} · SECTION ${esc(c.section)}</span><h1>${esc(c.name)}</h1><p>${esc(c.description)}</p><div class="actions"><span class="pill">${icon('users')} ${c.students.length} students</span><span class="pill">Class code: ${esc(c.code)}</span>${teacher()?btn(c.archivedAt?'Restore class':'Archive class',c.archivedAt?'restore':'archive','archive','small',`data-id="${c.id}"`):''}</div></div><div class="tabs">${Object.entries(names).map(([key,label])=>`<button class="${tab===key?'active':''}" data-action="tab" data-tab="${key}">${label}</button>`).join('')}</div>${tab==='stream'?`<div class="columns"><section class="panel"><div class="section-head"><h2>Class stream</h2>${teacher()?btn('Announcement','post','plus','small') : ''}</div>${S.posts.filter(p=>p.classId===c.id).map(p=>`<article class="stream-post"><header><span class="avatar">${esc(initials(person(p.authorId).name))}</span><div><strong>${esc(person(p.authorId).name)}</strong><br><small>${fmt(p.createdAt)} at ${time(p.createdAt)}</small></div></header><p>${esc(p.text)}</p>${fileLink(p.fileId)}</article>`).join('')||empty('Start a conversation','Announcements from your teacher will appear here.')}</section><section class="panel"><h2>Coming up</h2><div class="space">${S.assignments.filter(a=>a.classId===c.id).map(assignmentRow).join('')||'<p class="muted">No assignments yet.</p>'}</div></section></div>`:tab==='classwork'?assignmentsView(c.id):tab==='materials'?materialsView(c.id):tab==='people'?`<section class="panel"><h2>Class members</h2>${[c.teacherId,...c.students].map(uid=>`<div class="list-row"><div class="avatar">${esc(initials(person(uid).name))}</div><div class="row-main"><h3>${esc(person(uid).name)}</h3><p>${uid===c.teacherId?'Teacher':'Student'}</p></div></div>`).join('')}</section>`:gradesTable(c.id)}`;}
function fileLink(id){return id?`<a class="btn small space" href="/api/files/${encodeURIComponent(id)}">${icon('download')} Download attachment</a>`:'';}
function assignmentRow(a){const subs=S.submissions.filter(s=>s.assignmentId===a.id),mine=subs.find(s=>s.studentId===S.user.id);const status=teacher()?`${subs.length} submitted`:mine?(mine.grade!==null?'Graded':mine.late?'Late':'Submitted'):'Pending';return `<div class="list-row"><span class="row-icon ${!mine?'amber':''}">${icon('file')}</span><div class="row-main"><h3>${esc(a.title)}</h3><p>${esc(cls(a.classId)?.subject)} · Due ${fmt(a.due)} · ${a.points} points</p></div><div class="row-end"><button class="text-btn" data-action="assignment" data-id="${a.id}">${teacher()?'Review':'View'} ${icon('arrow')}</button><small><span class="pill ${mine?'green':'amber'}">${status}</span></small></div></div>`;}
function assignmentsView(cid){const list=S.assignments.filter(a=>!cid||a.classId===cid);return heading(cid?'Classwork':'Assignments','Small milestones. Meaningful progress.',teacher()?btn('New assignment','create-assignment','plus','primary',cid?`data-class="${cid}"`:''):'')+`<section class="panel">${list.length?list.map(assignmentRow).join(''):empty('No assignments yet','Your upcoming work will appear here.')}</section>`;}
function gradesTable(cid){const subs=S.submissions.filter(s=>!cid||S.assignments.some(a=>a.id===s.assignmentId&&a.classId===cid));return `<section class="panel"><h2>Submission & grade book</h2><div class="table-wrap space"><table><thead><tr><th>Student</th><th>Assignment</th><th>Status</th><th>Grade</th><th>Feedback</th>${teacher()?'<th>Review</th>':''}</tr></thead><tbody>${subs.map(s=>{const a=S.assignments.find(a=>a.id===s.assignmentId);return `<tr><td>${esc(person(s.studentId).name)}</td><td>${esc(a.title)}</td><td><span class="pill ${s.late?'amber':'green'}">${s.grade!==null?'Graded':s.late?'Late':'Submitted'}</span></td><td>${s.grade??'—'} / ${a.points}</td><td>${esc(s.feedback||'Awaiting review')}</td>${teacher()?`<td>${btn('Review','grade','','small',`data-id="${s.id}"`)}</td>`:''}</tr>`;}).join('')}</tbody></table>${subs.length?'':empty('No submissions yet','Grades will appear after work is submitted.')}</div></section>`;}
function attendanceView(){return heading('Attendance','A quick check-in. More time for learning.',teacher()?btn('Start QR session','attendance-session','qr','primary'):student()?btn('Enter attendance code','checkin','qr','primary'):'')+`<div class="stats">${stat('Recorded days',new Set(S.attendanceSessions.map(s=>s.classId+s.date)).size,'calendar','Across your classes')}${stat('Attendance rate',percent(average('attendance')),'chart','Present, late and excused count')}${stat('Active QR sessions',S.attendanceSessions.filter(s=>s.expires>Date.now()).length,'qr','Timed, secure classroom check-in')}${stat('Present records',S.attendance.filter(a=>a.status==='present').length,'check','Attendance recorded')}</div><section class="panel"><div class="section-head"><h2>Attendance register</h2>${teacher()?btn('Mark manually','manual-attendance','plus','small'):''}</div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Class</th><th>Date</th><th>Status</th></tr></thead><tbody>${S.attendance.slice().reverse().map(a=>`<tr><td>${esc(person(a.studentId).name)}</td><td>${esc(cls(a.classId)?.name)}</td><td>${fmt(a.date)}</td><td><span class="pill ${a.status==='absent'?'red':a.status==='late'?'amber':'green'}">${a.status}</span></td></tr>`).join('')}</tbody></table>${S.attendance.length?'':empty('Ready when you are','Start an attendance session, or use a code from your teacher.')}</div></section>`;}
function quizzesView(){return heading('A little challenge. A lot of learning.','Explore quizzes and let your voice be heard.',teacher()?btn('Create quiz','create-quiz','plus','primary')+btn('Create poll','create-poll','chart'):'')+`<div class="resource-grid">${S.quizzes.map(q=>{const a=S.attempts.find(a=>a.quizId===q.id&&a.studentId===S.user.id);return `<article class="panel"><span class="pill ${q.status==='live'?'green':''}">${esc(q.status)}</span><h3>${esc(q.title)}</h3><p class="muted">${esc(cls(q.classId)?.subject)} · ${q.questions.length} questions · ${q.minutes} min</p><div class="actions space">${teacher()?['draft','live','closed'].filter(s=>s!==q.status).map(s=>btn('Set '+s,'quiz-status','','small',`data-id="${q.id}" data-status="${s}"`)).join(''):student()?a?.submittedAt?`<span class="pill green">Score: ${a.score}/${a.total}${a.expired?' · Timed out':''}</span>`:q.status==='live'?btn(a?'Continue quiz':'Start quiz','take-quiz','arrow','primary small',`data-id="${q.id}"`):'<span class="muted">Quiz closed</span>':''}</div></article>`;}).join('')}</div>${S.quizzes.length?'':empty('No quizzes yet','Live quizzes will appear here.')}<h2 class="space">Class polls</h2><div class="resource-grid space">${S.polls.map(p=>`<article class="panel"><span class="eyebrow">${esc(cls(p.classId)?.subject)}</span><h3>${esc(p.title)}</h3>${p.options.map((o,i)=>{const total=p.counts.reduce((a,b)=>a+b,0);return `<div class="space"><div class="section-head"><span>${esc(o)}</span><span>${total?Math.round(p.counts[i]/total*100):0}%</span></div><div class="progress"><span style="width:${total?p.counts[i]/total*100:0}%"></span></div>${student()&&p.myVote===undefined?btn('Vote','vote','','small',`data-id="${p.id}" data-option="${i}"`):''}</div>`;}).join('')}<p class="help">${p.counts.reduce((a,b)=>a+b,0)} votes${p.myVote!==undefined?' · You voted':''}</p></article>`).join('')||'<p class="muted">No active polls.</p>'}</div>`;}
function analyticsView(){return heading('See the bigger picture','Progress is more than a number. Find your next step.')+`<section class="stats">${stat('Average grade',percent(average('average')),'file','Normalized to assignment points')}${stat('Attendance',percent(average('attendance')),'qr','Recorded class days')}${stat('Quiz average',percent(average('quiz')),'check','Completed quiz attempts')}${stat('Submission rate',percent(average('submission')),'chart','Assignments handed in')}</section><section class="panel"><div class="section-head"><h2>Performance overview</h2><span class="pill">From your classroom records</span></div><div class="chart-wrap"><canvas id="performance-chart" role="img" aria-label="Academic performance percentages"></canvas></div></section><section class="panel"><h2>Student progress</h2><div class="table-wrap space"><table><thead><tr><th>Student</th><th>Grade</th><th>Attendance</th><th>Quizzes</th><th>Submitted</th><th>Report</th></tr></thead><tbody>${S.analytics.map(a=>`<tr><td>${esc(a.name)}</td><td>${percent(a.average)}</td><td>${percent(a.attendance)}</td><td>${percent(a.quiz)}</td><td>${percent(a.submission)}</td><td><a class="btn small" href="/api/reports/${a.studentId}">${icon('download')} CSV</a></td></tr>`).join('')}</tbody></table>${S.analytics.length?'':empty('No student data yet','Join students to your classes, or approve a guardian link.')}</div></section>${gradesTable()}`;}
function drawChart(){chart=new Chart($('#performance-chart'),{type:'bar',data:{labels:['Assignment grade','Attendance','Quiz average','Submission rate'],datasets:[{label:'Average %',data:['average','attendance','quiz','submission'].map(average),backgroundColor:['#9f8af7','#6bb9aa','#dfb275','#7d9ed2'],borderRadius:5,maxBarThickness:44}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>c.raw+'%'}}},scales:{x:{grid:{display:false},ticks:{color:'#9496ad',font:{size:10}},border:{display:false}},y:{min:0,max:100,ticks:{stepSize:25,color:'#777a92',font:{size:10}},grid:{color:'#292b3a'},border:{display:false}}}}});}
function calendarView(){const date=new Date();date.setDate(1);date.setMonth(date.getMonth()+monthOffset);const year=date.getFullYear(),month=date.getMonth(),start=(date.getDay()+6)%7,days=new Date(year,month+1,0).getDate();const events=[...S.events.map(e=>({...e,date:e.start,meeting:true})),...S.assignments.map(a=>({...a,date:a.due,meeting:false}))];return heading('Make room for what’s next','Your classes, deadlines, and moments to connect.',teacher()?btn('Schedule meeting','create-event','video','primary'):'')+`<section class="panel"><div class="section-head"><h2>${date.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</h2><div class="actions">${btn('←','month','','small','data-direction="-1"')}${btn('Today','month','','small','data-direction="0"')}${btn('→','month','','small','data-direction="1"')}</div></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="calendar-week">${d}</div>`).join('')}${Array.from({length:Math.ceil((start+days)/7)*7},(_,i)=>{const day=i-start+1;const key=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;return `<div class="calendar-day ${day<1||day>days?'dim':''} ${key===new Date().toLocaleDateString('en-CA')?'today':''}">${day>0&&day<=days?day:''}${day>0&&day<=days?events.filter(e=>e.date.slice(0,10)===key).map(e=>`<button class="event" data-action="${e.meeting?'meeting':'assignment'}" data-id="${e.id}" title="${esc(e.title)}">${esc(e.title)}</button>`).join(''):''}</div>`;}).join('')}</div></section><section class="panel"><h2>Scheduled meetings</h2>${S.events.map(e=>`<div class="list-row"><div class="row-icon">${icon('video')}</div><div class="row-main"><h3>${esc(e.title)}</h3><p>${fmt(e.start)} · ${time(e.start)} · ${esc(cls(e.classId)?.subject)}</p></div><a class="btn small" href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Join meeting ${icon('arrow')}</a></div>`).join('')||empty('No meetings scheduled','Add your Google Meet or Zoom link to bring the class together.')}</section>`;}
function materialsView(cid){const list=S.materials.filter(m=>!cid||m.classId===cid);return heading('A place for every resource','Keep the good stuff close. Learn at your own pace.',teacher()?btn('Add material','create-material','plus','primary',cid?`data-class="${cid}"`:''):'')+`<div class="resource-grid">${list.map(m=>`<article class="panel"><span class="row-icon">${icon(m.fileId?'file':'link')}</span><h3>${esc(m.title)}</h3><p class="help">${esc(cls(m.classId)?.name)} · ${fmt(m.createdAt)}</p>${m.fileId?fileLink(m.fileId):`<a class="btn small" href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">Open resource ${icon('arrow')}</a>`}</article>`).join('')}</div>${list.length?'':empty('Your resource shelf is ready','Upload notes, documents, or useful links for your classes.')}`;}
function messagesView(){if(!chatTarget){const c=activeClasses()[0];if(c)chatTarget={type:'class',id:c.id};}const messages=S.messages.filter(m=>chatTarget?.type==='class'?m.classId===chatTarget.id:!m.classId&&[m.to,m.from].includes(chatTarget?.id));return heading('Good conversations start here','Ask a question, share an idea, stay connected.')+`<section class="panel chat-layout"><aside class="chat-contacts"><span class="eyebrow">CLASSROOMS & PEOPLE</span>${activeClasses().map(c=>`<button class="nav-item ${chatTarget?.id===c.id?'active':''}" data-action="chat-target" data-id="${c.id}" data-type="class">${icon('book')}${esc(c.subject)}</button>`).join('')}${S.contacts.map(c=>`<button class="nav-item ${chatTarget?.id===c.id?'active':''}" data-action="chat-target" data-id="${c.id}" data-type="user">${icon('chat')}${esc(c.name)}</button>`).join('')}</aside><div class="chat-body"><h3>${chatTarget?esc(chatTarget.type==='class'?cls(chatTarget.id)?.name:person(chatTarget.id).name):'Choose a conversation'}</h3><div class="chat-messages">${messages.map(m=>`<div class="bubble ${m.from===S.user.id?'mine':''}"><small>${esc(person(m.from).name)} · ${time(m.createdAt)}</small>${esc(m.text)}</div>`).join('')||empty('Say hello','This is the beginning of a conversation.')}</div>${chatTarget?'<form id="chat-form" class="chat-compose"><input class="control" name="text" aria-label="Message" placeholder="Write a thoughtful message…" required maxlength="3000"><button class="btn primary" type="submit">Send</button></form>':''}</div></section>`;}
function bindChat(){const form=$('#chat-form');if(form)form.onsubmit=async e=>{e.preventDefault();const text=form.elements.text.value;await act(()=>api('/messages',{text,...(chatTarget.type==='class'?{classId:chatTarget.id}:{to:chatTarget.id})}),'Message sent.');};const area=$('.chat-messages');if(area)area.scrollTop=area.scrollHeight;}
function notificationsView(){return heading('You’re in the loop','Classroom updates, all in one place.',btn('Mark all as read','read-notifications','check'))+`<section class="panel">${S.notifications.map(n=>`<div class="list-row"><div class="row-icon">${icon('bell')}</div><div class="row-main"><h3>${esc(n.text)}</h3><p>${fmt(n.createdAt)} · ${time(n.createdAt)}</p></div>${!n.read?'<span class="pill">New</span>':''}</div>`).join('')||empty('All quiet for now','We’ll keep you posted on your classroom activity.')}</section>`;}
function archiveView(){return heading('Room for a fresh start','Archived classrooms can be restored for 48 hours.')+`<div class="resource-grid">${S.classes.filter(c=>c.archivedAt).map(c=>`<section class="panel"><span class="pill">Archived ${fmt(c.archivedAt)}</span><h3 class="space">${esc(c.name)}</h3><p class="help">${Date.now()-Date.parse(c.archivedAt)<172800000?'Within the 48-hour restore window.':'Restore window has ended. Records are retained in this local edition.'}</p>${teacher()&&Date.now()-Date.parse(c.archivedAt)<172800000?btn('Restore class','restore','archive','small',`data-id="${c.id}"`):''}</section>`).join('')}</div>${S.classes.some(c=>c.archivedAt)?'':empty('Nothing archived','Your active classrooms are right where you left them.')}`;}
function profileView(){return heading('Make yourself at home','Your profile helps your classroom get to know you.')+`<section class="panel" style="max-width:680px"><div class="list-row"><div class="avatar">${esc(initials(S.user.name))}</div><div><h2>${esc(S.user.name)}</h2><p class="muted">${esc(S.user.email)} · ${S.user.role}</p></div></div><form id="profile-form" class="space">${field('Full name','name','text',S.user.name,true)}${field('Phone','phone','tel',S.user.phone)}${textarea('A little about you','bio',S.user.bio)}<button class="btn primary" type="submit">Save changes</button></form></section>`;}
function guardianView(){return heading(student()?'You’re in control':'A window into their learning',student()?'Choose who can see your academic progress.':'Guardian access always starts with student approval.',S.user.role==='guardian'?btn('Link a student','link-student','link','primary'):'')+`<section class="panel">${S.links.map(l=>`<div class="list-row"><div class="avatar">${esc(initials(person(student()?l.guardianId:l.studentId).name))}</div><div class="row-main"><h3>${esc(person(student()?l.guardianId:l.studentId).name)}</h3><p>Access request · ${l.status}</p></div><div class="actions">${student()?l.status==='pending'?btn('Approve','link-status','check','primary small',`data-id="${l.id}" data-status="approved"`)+btn('Decline','link-status','','small',`data-id="${l.id}" data-status="rejected"`):l.status==='approved'?btn('Revoke access','link-status','','small danger',`data-id="${l.id}" data-status="rejected"`):'':l.status==='approved'?`<a class="btn small" href="/api/reports/${l.studentId}">${icon('download')} Progress report</a>`:''}</div></div>`).join('')||empty('No connected accounts',student()?'Guardian requests will appear here for your approval.':'Send a link request using your student’s registered email address.')}</section>${S.user.role==='guardian'&&S.analytics.length?analyticsView():''}`;}
let aiConversation=[];
function aiView(){return heading('A little guidance goes a long way','Your space to ask, explore, and understand.')+`${!S.aiConfigured?'<div class="inline-note">AI is not connected yet. To enable it, set OPENROUTER_API_KEY and OPENROUTER_MODEL in the server’s .env file.</div>':''}<section class="panel"><div class="section-head"><h2>${icon('spark')} SmartClass assistant</h2><span class="pill">Learning companion</span></div><div class="chat-messages" id="ai-messages">${aiConversation.length?aiConversation.map(m=>`<div class="bubble ${m.role==='user'?'mine':''}">${esc(m.text)}</div>`).join(''):empty('What are you curious about?','Ask for an explanation, a study plan, or help breaking down a difficult concept.')}</div><form id="ai-form" class="chat-compose"><input class="control" name="message" aria-label="Ask the AI assistant" placeholder="Help me understand…" maxlength="2000" required><button class="btn primary" ${!S.aiConfigured?'disabled':''}>${icon('arrow')} Send</button></form><p class="help">AI can make mistakes. Check important information with your course materials.</p></section>`;}
function bindAI(){const form=$('#ai-form');form.onsubmit=async e=>{e.preventDefault();const message=form.elements.message.value;const b=$('button',form);b.disabled=true;try{const r=await api('/ai',{message});aiConversation.push({role:'user',text:message},{role:'assistant',text:r.reply});renderPage();}catch(e){toast(e.message,true);b.disabled=false;}};}
function searchView(){const classes=S.classes.filter(c=>(c.name+' '+c.subject).toLowerCase().includes(search)),assignments=S.assignments.filter(a=>a.title.toLowerCase().includes(search));return heading('Search results',`Results for “${esc(search)}”`)+`<div class="class-grid">${classes.map(classCard).join('')}</div><section class="panel">${assignments.map(assignmentRow).join('')||(!classes.length?empty('No matches','Try another class, course code, or assignment title.'):'<p class="muted">No matching assignments.</p>')}</section>`;}
function field(label,name,type='text',value='',required=false){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'minlength="8" maxlength="72"':''}></label>`;}
function textarea(label,name,value='',required=false){return `<label class="field">${label}<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea></label>`;}
function select(label,name,options,value){return `<label class="field">${label}<select name="${name}" required>${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function classSelect(cid){return select('Class','classId',activeClasses().map(c=>[c.id,c.name]),cid||classId);}
function uploadField(){return '<label class="field">Attachment (optional, up to 4 MB)<input name="file" type="file" accept=".pdf,.txt,.png,.jpg,.jpeg,.docx,.pptx,.xlsx,.csv,.zip"></label>';}
function modal(title,html,submit,callback){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${submit?'<form id="modal-form">':''}${html}${submit?`<div id="form-error"></div><div class="modal-foot">${btn('Cancel','close-modal')}<button type="submit" class="btn primary">${submit}</button></div></form>`:''}`;if(!d.open)d.showModal();if(submit)$('#modal-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{const values=Object.fromEntries(new FormData(e.target));if(values.file?.size){if(values.file.size>4*1024*1024)throw Error('File must be smaller than 4 MB.');const fd=new FormData();fd.append('file',values.file);values.fileId=(await api('/upload',fd)).id;}delete values.file;await callback(values,e.target);if(d.open)d.close();await refresh();renderPage();}catch(err){if($('#form-error'))$('#form-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;else toast(err.message,true);}finally{button.disabled=false;}};}
async function act(fn,message){try{await fn();await refresh();render();if(message)toast(message);}catch(e){toast(e.message,true);}}
function assignmentModal(aid){const a=S.assignments.find(a=>a.id===aid);const mine=S.submissions.find(s=>s.assignmentId===a.id&&s.studentId===S.user.id);const info=`<span class="pill">${esc(cls(a.classId)?.subject)} · ${a.points} points · Due ${fmt(a.due)} ${time(a.due)}</span><p class="detail-text space">${esc(a.description)}</p>${fileLink(a.fileId)}`;if(teacher()){modal(a.title,info+`<h3 class="space">Submissions</h3>${S.submissions.filter(s=>s.assignmentId===a.id).map(s=>`<div class="list-row"><div class="row-main"><h3>${esc(person(s.studentId).name)}</h3><p>${s.grade===null?'Awaiting grade':s.grade+'/'+a.points}${s.late?' · Late':''}</p></div>${btn('Review','grade','','small',`data-id="${s.id}"`)}</div>`).join('')||'<p class="help">No submissions yet.</p>'}<div class="space">${btn('Verify offline token','verify-offline','qr','small')}</div>`);return;}if(!student()){modal(a.title,info);return;}if(mine){modal(a.title,info+`<div class="inline-note space">${mine.grade===null?'Your work is submitted. Awaiting teacher feedback.':`Grade: ${mine.grade}/${a.points}`}${mine.late?' · Submitted late':''}</div><p class="detail-text">${esc(mine.text)}</p>${fileLink(mine.fileId)}<h3 class="space">Teacher feedback</h3><p class="detail-text muted">${esc(mine.feedback||'No feedback yet.')}</p>`);return;}modal(a.title,info+`<div class="space">${textarea('Your answer','text')}</div>${uploadField()}<p class="help">One submission per assignment. Review your work before submitting.</p>${btn('Create offline hand-in token','offline-token','qr','small',`data-id="${a.id}"`)}`,'Submit assignment',async b=>{await api(`/assignments/${a.id}/submit`,b);toast('Assignment submitted.');});}
async function takeQuiz(qid){const q=S.quizzes.find(q=>q.id===qid);const attempt=await api(`/quizzes/${qid}/start`,{});modal(q.title,`<p class="help">One attempt · Answers are graded automatically.</p><p class="timer" id="quiz-timer"></p>${q.questions.map((q,i)=>`<fieldset class="quiz-question" style="border:0;padding:0"><legend>${i+1}. ${esc(q.text)}</legend>${q.options.map((o,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}">${esc(o)}</label>`).join('')}</fieldset>`).join('')}`,'Submit quiz',async b=>{clearInterval(quizTimer);const result=await api(`/quizzes/${qid}/submit`,{answers:q.questions.map((_,i)=>b['q'+i]===undefined?-1:Number(b['q'+i]))});toast(`Quiz complete! Your score: ${result.score}/${result.total}.`);});const tick=()=>{const left=Math.max(0,Math.ceil((attempt.deadline-Date.now())/1000));if($('#quiz-timer'))$('#quiz-timer').textContent=`Time remaining: ${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;if(left===0){clearInterval(quizTimer);if($('#modal-form'))$('#modal-form').requestSubmit();}};tick();quizTimer=setInterval(tick,1000);}
async function checkAttendanceLink(){const token=new URLSearchParams(location.search).get('attendance');if(token&&student()){await act(()=>api('/attendance/checkin',{token}),'You’re checked in!');history.replaceState({},'',location.pathname);goto('attendance');}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;try{switch(a){
case 'auth-switch':renderAuth(el.dataset.register==='true');break;
case 'demo':el.disabled=true;await api('/auth/login',{email:el.dataset.role+'@smartclass.local',password:'password123'});await refresh();chatTarget=null;goto('dashboard');await checkAttendanceLink();break;
case 'nav':goto(el.dataset.page);break;
case 'menu':$('.sidebar').classList.toggle('open');break;
case 'logout':await api('/logout',{});localStorage.removeItem('smartclass-offline-'+S.user.id);sessionStorage.removeItem('smartclass-user');S=null;aiConversation=[];chatTarget=null;renderAuth();break;
case 'close-modal':$('#modal').close();if(quizTimer)clearInterval(quizTimer);break;
case 'open-class':goto('class',el.dataset.id);break;
case 'tab':tab=el.dataset.tab;renderPage();break;
case 'create-class':modal('Create a learning space',field('Class name','name','text','',true)+`<div class="form-grid">${field('Subject code','subject','text','',true)}${field('Section','section','text','',true)}${field('Room','room')}${field('Student limit','limit','number',40,true)}</div>`+textarea('Description','description')+field('Class color','color','color','#9784f7'),'Create class',async b=>{await api('/classes',b);toast('Your class is ready. Share its code with students.');});break;
case 'join-class':modal('Join your classroom','<p class="help">Ask your teacher for the 7-character class code.</p>'+field('Class code','code','text','',true),'Join class',async b=>{await api('/classes/join',b);toast('Welcome to your new class.');});break;
case 'archive':modal('Archive this classroom?','<p>You can restore it within 48 hours. Students cannot submit work to archived classes.</p>','Archive class',()=>api(`/classes/${el.dataset.id}/archive`,{}));break;
case 'restore':await act(()=>api(`/classes/${el.dataset.id}/archive`,{restore:true}),'Class restored.');break;
case 'post':modal('Share with your class',classSelect()+textarea('Announcement','text','',true)+uploadField()+'<label class="check"><input type="checkbox" name="broadcast">Share with all my active classes</label>','Post announcement',b=>api('/posts',{...b,broadcast:!!b.broadcast}));break;
case 'create-assignment':modal('Create an assignment',classSelect(el.dataset.class)+field('Title','title','text','',true)+textarea('Instructions','description','',true)+`<div class="form-grid">${field('Due date','due','datetime-local','',true)}${field('Points','points','number',100,true)}</div>`+uploadField(),'Create assignment',b=>api('/assignments',b));break;
case 'assignment':assignmentModal(el.dataset.id);break;
case 'grade':{const s=S.submissions.find(s=>s.id===el.dataset.id),a=S.assignments.find(a=>a.id===s.assignmentId);modal('Review submission',`<span class="pill">${esc(person(s.studentId).name)} · ${esc(a.title)}</span><p class="detail-text space">${esc(s.text)}</p>${fileLink(s.fileId)}<div class="space">${field('Grade (0–'+a.points+')','grade','number',s.grade??'',true)}</div>${textarea('Feedback','feedback',s.feedback)}`,'Save grade',b=>api(`/submissions/${s.id}/grade`,b));break;}
case 'attendance-session':modal('Start a QR attendance session',classSelect()+field('Duration in minutes (1–60)','minutes','number',10,true),'Generate QR code',async b=>{const r=await api('/attendance/sessions',b);setTimeout(()=>{modal('Your class is checking in',`<p class="help">Students scan this code with their phone camera while signed in. Expires at ${time(r.expires)}.</p><img class="qr" src="${r.qr}" alt="Attendance check-in QR code"><p class="help">For a phone, BASE_URL must point to this computer’s network address.</p><p class="token">${esc(r.token)}</p><p class="help">Students can also paste the code above in Attendance.</p><div id="live-checkins" class="inline-note">Waiting for check-ins…</div>`);},0);});break;
case 'checkin':modal('Check in to class',textarea('Attendance token or QR link','token','',true),'Check in',b=>{let token=b.token.trim();try{token=new URL(token).searchParams.get('attendance')||token;}catch{}return api('/attendance/checkin',{token});});break;
case 'manual-attendance':{const c=activeClasses()[0];if(!c)throw Error('Create a class first.');modal('Record attendance',classSelect(c.id)+select('Student','studentId',c.students.map(id=>[id,person(id).name]))+field('Class date','date','date',new Date().toISOString().slice(0,10),true)+select('Status','status',['present','absent','late','excused'].map(s=>[s,s])),'Save attendance',b=>api('/attendance/manual',b));$('#modal-form [name=classId]').onchange=e=>{$('#modal-form [name=studentId]').innerHTML=cls(e.target.value).students.map(id=>`<option value="${id}">${esc(person(id).name)}</option>`).join('');};break;}
case 'create-quiz':modal('Create a quiz',classSelect()+field('Quiz title','title','text','',true)+field('Time limit (minutes)','minutes','number',10,true)+'<p class="help">One question per line. Format: Question | Option A | Option B | Option C | Option D | Correct option (1–4)</p>'+textarea('Questions','questions','What does SRS stand for? | System Runtime Service | Software Requirements Specification | Software Release Standard | Secure Remote Server | 2',true),'Create draft',b=>api('/quizzes',{...b,questions:b.questions.split('\n').filter(x=>x.trim()).map(line=>{const bits=line.split('|').map(x=>x.trim());return {text:bits[0],options:bits.slice(1,-1),answer:Number(bits.at(-1))-1};})}));break;
case 'quiz-status':await act(()=>api(`/quizzes/${el.dataset.id}/status`,{status:el.dataset.status}),'Quiz status updated.');break;
case 'take-quiz':await takeQuiz(el.dataset.id);break;
case 'create-poll':modal('Ask your class',classSelect()+field('Poll question','title','text','',true)+textarea('Options (one per line, 2–6)','options','',true),'Create poll',b=>api('/polls',{...b,options:b.options.split('\n').filter(x=>x.trim())}));break;
case 'vote':await act(()=>api(`/polls/${el.dataset.id}/vote`,{option:Number(el.dataset.option)}),'Your vote is in.');break;
case 'link-student':modal('Connect with your student','<p class="help">Your student must approve the request before you can see grades, attendance, and reports.</p>'+field('Student email','email','email','',true),'Send request',b=>api('/links',b));break;
case 'link-status':await act(()=>api(`/links/${el.dataset.id}`,{status:el.dataset.status}),'Guardian access updated.');break;
case 'create-material':modal('Add learning material',classSelect(el.dataset.class)+field('Resource title','title','text','',true)+field('Resource link (or upload a file)','url','url')+uploadField()+'<label class="check"><input name="broadcast" type="checkbox">Share with all my active classes</label>','Add material',b=>api('/materials',{...b,broadcast:!!b.broadcast}));break;
case 'create-event':modal('Bring your class together',classSelect()+field('Meeting title','title','text','',true)+field('Start time','start','datetime-local','',true)+field('Google Meet / Zoom / HTTPS meeting link','url','url','',true),'Schedule meeting',b=>api('/events',b));break;
case 'meeting':{const event=S.events.find(x=>x.id===el.dataset.id);modal(event.title,`<p>${fmt(event.start)} at ${time(event.start)}</p><a class="btn primary space" href="${esc(event.url)}" target="_blank" rel="noopener noreferrer">Join meeting</a>`);break;}
case 'month':monthOffset=el.dataset.direction==='0'?0:monthOffset+Number(el.dataset.direction);renderPage();break;
case 'chat-target':chatTarget={type:el.dataset.type,id:el.dataset.id};renderPage();break;
case 'read-notifications':await act(()=>api('/notifications/read',{}),'All caught up.');break;
case 'verify-offline':modal('Verify an offline hand-in','<p class="help">Check the student’s identity and physical work before verifying. Offline tokens identify the hand-in; they do not prove identity.</p>'+textarea('Student’s offline token','token','',true),'Verify submission',b=>api('/offline/verify',b));break;
case 'offline-token':{const token=localStorage.getItem('smartclass-token-'+S.user.id+'-'+el.dataset.id)||JSON.stringify({assignmentId:el.dataset.id,studentId:S.user.id,nonce:crypto.randomUUID()});localStorage.setItem('smartclass-token-'+S.user.id+'-'+el.dataset.id,token);modal('Offline hand-in token','<p class="help">Saved on this device. Show this token and your completed work to your teacher for in-person verification.</p><canvas id="offline-qr" class="qr"></canvas><p class="token">'+esc(token)+'</p><p class="help">This token identifies your hand-in. Your teacher must verify your identity and work.</p>');await offlineQR(token);break;}
}}catch(err){toast(err.message,true);el.disabled=false;}});
async function offlineQR(token){if(window.QRCode)window.QRCode.toCanvas($('#offline-qr'),token,{width:230});else $('#offline-qr')?.remove();}
$('#modal').addEventListener('close',()=>{if(quizTimer)clearInterval(quizTimer);});
setInterval(async()=>{if(!S||document.hidden)return;if(!['attendance','messages','quizzes'].includes(page)&&!$('#live-checkins'))return;try{const editing=document.activeElement?.matches('input,textarea,select');await refresh();if($('#live-checkins'))$('#live-checkins').textContent=`${S.attendance.filter(a=>a.date===new Date().toISOString().slice(0,10)&&a.status==='present').length} present records today. Refreshes every 3 seconds.`;if(!$('#modal').open&&!editing)renderPage();}catch{}},3000);
(async()=>{try{await refresh();render();await checkAttendanceLink();}catch{if(!navigator.onLine)renderOffline();else renderAuth();}if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});})();

function renderOffline(){
 const uid=sessionStorage.getItem('smartclass-user');
 const cached=uid?JSON.parse(localStorage.getItem('smartclass-offline-'+uid)||'null'):null;
 if(!cached||cached.user.role!=='student'){renderAuth();toast('Connect to the internet to sign in. Offline hand-ins are available after a student signs in on this device.',true);return;}
 S=cached;
 $('#app').innerHTML='<main class="content" style="max-width:900px">'+brand()+heading('Your offline classroom','Your saved assignments are available on this device. Reconnect for grades, messages and submissions.')+'<div class="inline-note">You are offline. Generate a hand-in QR token below and show it with your work to your teacher.</div><section class="panel">'+cached.assignments.map(a=>'<div class="list-row"><div class="row-main"><h3>'+esc(a.title)+'</h3><p>Due '+fmt(a.due)+'</p><p>'+esc(a.description)+'</p></div>'+btn('Hand-in token','offline-token','qr','small','data-id="'+a.id+'"')+'</div>').join('')+'</section></main>';
}
window.addEventListener('offline',()=>{if(S?.user?.role==='student'&&!$('#modal').open)renderOffline();});
window.addEventListener('online',async()=>{try{await refresh();goto('dashboard');toast('You are back online.');}catch{renderAuth();}});
